const themes = [
  { category: '开源程序教程', instruction: '选择一款知名开源程序/项目，写一篇实用教程：如何安装、配置、使用，以及应用场景与技巧。' },
  { category: '主机测评', instruction: '写一篇主机/虚拟主机/VPS测评或选购指南。注意：不要编造具体价格、性能跑分、配置数字或厂商承诺，若涉及具体参数请注明"以官方文档/官网为准"，重点写选购标准、适用场景、注意事项等真实客观内容。' },
  { category: '服务器运维', instruction: '写一篇服务器运维实战教程，主题如 Linux 常用命令、日常巡检、安全加固、备份恢复、日志分析等。' },
  { category: 'WordPress优化', instruction: '写一篇 WordPress 优化教程，如性能优化、缓存配置、SEO优化、安全加固、插件推荐等。' },
  { category: '在线工具教程', instruction: '写一篇在线工具的使用教程，选择一个实用的在线工具，介绍其功能、使用方法、优缺点与注意事项。' },
  { category: 'Python/PHP入门', instruction: '写一篇 Python 或 PHP 入门教程，主题如环境搭建、基础语法、常用库/框架、小实战项目等。' }
];
const pick = themes[Math.floor(Math.random() * themes.length)];
return [{ json: { category: pick.category, instruction: pick.instruction } }];

const raw = $json.output || '{}';
let parsed = {};
let s = String(raw).trim();
const m = s.match(/```(?:json)?\s*([\s\S]*?)```/);
if (m) s = m[1].trim();
const start = s.indexOf('{');
const end = s.lastIndexOf('}');
if (start !== -1 && end !== -1) s = s.slice(start, end + 1);
try {
  parsed = JSON.parse(s);
} catch (e) {
  throw new Error('AI输出无法解析为JSON: ' + e.message + ' | 原文: ' + raw);
}
let title = String(parsed.title || '').trim();
let slug = String(parsed.slug || '').trim();
if (!slug && title) {
  slug = title.toLowerCase().replace(/[^\w\u4e00-\u9fa5]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
}
return [{ json: {
  title: title,
  slug: slug,
  excerpt: String(parsed.excerpt || '').trim(),
  content: String(parsed.content || '').trim(),
  category: String(parsed.category || '未分类').trim(),
  tags: Array.isArray(parsed.tags) ? parsed.tags.map(t => String(t).trim()).filter(Boolean) : []
} }];

const posts = $input.all();
const art = $('Code - 解析AI输出').all()[0].json;
const targetSlug = String(art.slug || '').trim();
const isDuplicate = Boolean(targetSlug) && posts.some(item => String(item.json?.slug || '').trim() === targetSlug);
return [{ json: { ...art, isDuplicate } }];

const art = $('Code - 判断重复').first().json;
const defaults = ['技术教程', '实用技巧', '网站运维'];
const tagNames = [...new Set((Array.isArray(art.tags) ? art.tags : []).map(tag => String(tag).trim()).filter(Boolean))];
for (const tag of defaults) {
  if (tagNames.length >= 3) break;
  if (!tagNames.includes(tag)) tagNames.push(tag);
}
return [{ json: { ...art, category: String(art.category || '未分类').trim(), tagNames } }];

const response = $input.first().json;
const art = $('Code - 准备术语').first().json;
const termId = response.id ?? response.term_id ?? response.data?.term_id ?? response.error?.data?.term_id ?? response.error?.response?.data?.term_id;
const categoryId = Number(termId);
if (!Number.isInteger(categoryId) || categoryId <= 0) throw new Error('无法创建或取得分类 term_id: ' + JSON.stringify(response));
return [{ json: { ...art, categoryId } }];

const item = $json;
const names = Array.isArray(item.tagNames) ? item.tagNames : [];
return names.map(tagName => ({ json: { ...item, tagName } }));

const art = $('Code - 取得分类ID').first().json;
const finalTagIds = [...new Set($input.all().map(item => {
  const response = item.json;
  return Number(response.id ?? response.term_id ?? response.data?.term_id ?? response.error?.data?.term_id ?? response.error?.response?.data?.term_id);
}).filter(id => Number.isInteger(id) && id > 0))];
if (finalTagIds.length !== art.tagNames.length) throw new Error('无法创建或取得全部标签 term_id');
return [{ json: { ...art, finalTagIds } }];

const item = $json;
return [{ json: {
  title: item.title,
  content: item.content,
  slug: item.slug,
  excerpt: item.excerpt,
  status: 'publish',
  comment_status: 'open',
  categories: item.categoryId ? [Number(item.categoryId)] : [1],
  tags: Array.isArray(item.finalTagIds) ? item.finalTagIds.map(Number) : []
} }];
